const QA = [
  { type: 'placeholders', label: 'Placeholders', tr: false },
  { type: 'html', label: 'HTML', tr: false },
  { type: 'double_space', label: 'Double space', tr: true }
];
const out = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    const base = (p.base_language_iso || 'en').toLowerCase();
    for (const q of QA) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: q.type,
        qa_label: q.label,
        extra: q.tr ? '&include_translations=1' : ''
      }});
    }
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__',
        extra: ''
      }});
      first = false;
    }
  }
}
return out;

const LABELS = ['Placeholders', 'HTML', 'Double space (translations)', 'Double space (EN source)'];
const reqs = $('Build QA Requests').all();
const res = $input.all();
const rows = {};
const order = [];
const failed = [];
const truncated = [];
let controlStatus = null;

function isPseudo(iso) {
  const s = (iso || '').toLowerCase();
  return s === 'pst' || s.indexOf('pseudo') >= 0;
}

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;

  const r = res[i].json || {};
  const hdr = r.headers || {};

  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name + ' / ' + meta.qa_label); }

  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  if (total !== null && total > keys.length) { truncated.push(meta.project_name + ' / ' + meta.qa_label); }

  if (!rows[meta.project_name]) { rows[meta.project_name] = {}; order.push(meta.project_name); }

  if (meta.qa_label === 'Double space') {
    let srcCount = 0;
    let tgtCount = 0;
    for (const k of keys) {
      if (k.is_archived) { continue; }
      let inSrc = false;
      let inTgt = false;
      for (const tr of (k.translations || [])) {
        const v = tr.translation;
        if (typeof v !== 'string') { continue; }
        if (!/ {2,}/.test(v)) { continue; }
        const iso = (tr.language_iso || '').toLowerCase();
        if (iso === meta.base_lang) { inSrc = true; }
        else if (!isPseudo(iso)) { inTgt = true; }
      }
      if (inSrc) { srcCount++; }
      if (inTgt) { tgtCount++; }
    }
    rows[meta.project_name]['Double space (translations)'] = (total === null) ? null : tgtCount;
    rows[meta.project_name]['Double space (EN source)'] = (total === null) ? null : srcCount;
  } else {
    let active = 0;
    for (const k of keys) { if (!k.is_archived) { active++; } }
    rows[meta.project_name][meta.qa_label] = (total === null) ? null : active;
  }
}

const totals = {};
for (const l of LABELS) { totals[l] = 0; }
const flagged = [];
for (const name of order) {
  const r = rows[name];
  let sum = 0;
  for (const l of LABELS) {
    const v = r[l];
    if (typeof v === 'number') { sum += v; totals[l] += v; }
  }
  if (sum > 0) { flagged.push({ name: name, r: r, sum: sum }); }
}
flagged.sort(function (a, b) {
  return a.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase().localeCompare(b.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase());
});

const totalParts = [];
for (const l of LABELS) { totalParts.push(l + ': ' + totals[l]); }

let text = '*Lokalise nightly QA check* — ' + order.length + ' projects scanned\n';
text += '_Keys flagged per check, across all target languages. Archived keys and the pseudo-language excluded. EN source counted separately._\n\n';
text += '*Totals*\n';
for (const l of LABELS) { text += '• ' + l + ': ' + totals[l] + '\n'; }
text += '\n';

if (flagged.length === 0) {
  text += ':white_check_mark: No issues found in any project.\n';
} else {
  text += '*Projects with issues (' + flagged.length + ' of ' + order.length + ')*\n';
  for (const f of flagged) {
    const parts = [];
    for (const l of LABELS) {
      const v = f.r[l];
      if (typeof v === 'number' && v > 0) { parts.push(l + ': ' + v); }
    }
    text += '• *' + f.name + '* — ' + parts.join('  ·  ') + '\n';
  }
  text += '\n:white_check_mark: ' + (order.length - flagged.length) + ' project(s) clean.\n';
}

if (failed.length > 0) { text += '\n:warning: could not read: ' + failed.join(', '); }
if (truncated.length > 0) { text += '\n:warning: over 500 flagged keys, count is a floor: ' + truncated.join(', '); }
if (controlStatus !== 400) { text += '\n:rotating_light: control probe returned ' + controlStatus + ' instead of 400 — the QA filter may not be applied, treat these numbers as unverified.'; }

if (text.length > 3800) { text = text.slice(0, 3740) + '\n… truncated, see full run in n8n.'; }

return [{ json: { report: text, project_count: order.length, flagged_count: flagged.length, totals: totals, failures: failed.length, truncated: truncated.length, control_status: controlStatus } }];

